from taf.collectors.btslog.factory import BtslogCollectorFactorySelector
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class btslog(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_btslog_collector(self,
                                name,
                                btslog_path=None,
                                btslog_launcher_path=None,
                                executor=None,
                                sudo_password=None,
                                log_dir=None,
                                target_file_name=None,
                                poll_interval=None,
                                start_timeout=None,
                                teardown_timeout=None,
                                syslog_timeout=None,
                                btslog_configuration=None):
        """
            Create btslog Collector from given configuration.

            :param str name: alias name of the collector
            :param str btslog_path: (optional) path of the 'btslog' executable
                                     default value:"/opt/btslog/btslog"
            :param str btslog_launcher_path: (optional) path of 'btslog_launcher' executable
                                     default value:"/opt/btslog/btslog_launcher"
            :param dict executor: (optional) Executor configuration of collector:
                                     default value: None
                                     If value provided: mandatory: user, password, host
                                                         optional: port, proxy
            :param str sudo_password: (optional) password for sudo
            :param str log_dir: path from where to get btslog files
                                     default value: "/tmp/btslog2"
            :param str target_file_name: (optional) file_name.tgz format, its part of the path under which syslog file
                                            stored locally during collect_collectors
                                         default value: "syslog.tgz"
                There are two cases for the executor as mentioned below
                if executor is None, then btslog will be collected from the local machine to the target_path mentioned
                by the user.
                if executor is dictionary of remote machine details, then btslog will be collected from remote to local.
            :param float poll_interval: (optional) poll interval during btslog start (in seconds), default value: 0.1
                                           second
            :param float start_timeout: (optional) btslog start timeout in seconds, default value: 10 seconds
            :param float syslog_timeout: (optional) syslog file closer timeout in seconds, default value: 3 seconds
            :param float teardown_timeout: (optional) btslog stop timeout in seconds, default value: 60 seconds
            :param dict btslog_configuration: (optional) btslog configuration file or btslog.ini parameters need to be
                                              added/modified in {SECTION1:{option1_1: value1_1, option2_2: value2_2,..},
                                              SECTION2:{option2_1: value2_1, option2_2: value2_2, ..}, ..} format
        """
        configuration = {
            'name': name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["btslog_path", "btslog_launcher_path", "executor", "sudo_password",
                                  "log_dir", "target_file_name", "poll_interval", "start_timeout",
                                  "teardown_timeout", "syslog_timeout", "btslog_configuration_file",
                                  "btslog_configuration"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value

        logger.info("Creating btslog Collector with alias name " + name)
        btslog_collector = BtslogCollectorFactorySelector().create(configuration=configuration, existing_arguments={})
        self.set_alias(name, btslog_collector)
        logger.info("Btslog Collector created successfully")
